/// <summary>
/// Configure the forms and records from where to open the archive
/// </summary>
public class AVADAIArchiveFormConfig extends common
{
}

Method.Source:
/// <summary>
/// find form
/// </summary>
/// <param name = "AVADAIServerId">AVADAIServerId.</param>
/// <param name = "boolean">boolean</param>
/// <returns>A <c>AVADAIArchiveFormConfig</c> object.</returns>
public static AVADAIArchiveFormConfig find(AVADAIServerId _serverId, boolean _update = false)
{
    AVADAIArchiveFormConfig archiveFormConfig;

    archiveFormConfig.selectForUpdate(_update);

    if (_serverId != null)
    {
        select firstonly archiveFormConfig
            where archiveFormConfig.ServerId == _serverId;
    }
    return archiveFormConfig;
}

/// <summary>
/// find form
/// </summary>
/// <param name = "AVADAIForm">Import Id.</param>
/// <param name = "boolean">Server Id.</param>
/// <returns>A <c>AVADAIArchiveFormConfig</c> object.</returns>
public static AVADAIArchiveFormConfig findForm(AVADAIForm _form, boolean _update = false)
{
    AVADAIArchiveFormConfig archiveFormConfig;

    archiveFormConfig.selectForUpdate(_update);

    if (_form)
    {
        select firstonly archiveFormConfig
            where archiveFormConfig.ServerId == AVADAIParameters::find().ServerId
                && archiveFormConfig.Form == _form;
    }

    return archiveFormConfig;
}

/// <summary>
/// Checks if record exists in table.
/// </summary>
/// <param name = "AVADAIServerId">Server Id.</param>
/// <returns>A <c>boolean</c> object.</returns>
public static boolean exist(AVADAIServerId _serverId)
{
    AVADAIArchiveFormConfig archiveFormConfig;

    select firstonly RecId from archiveFormConfig
        where archiveFormConfig.ServerId == _serverId;

    return archiveFormConfig.RecId != 0;
}

    /// <summary>
    /// Checks if record exists in table.
    /// </summary>
    /// <param name = "AVADAIForm">AVADAIForm</param>
    /// <returns>A <c>boolean</c> object.</returns>
    public static boolean existForm(AVADAIForm _form)
    {
        AVADAIArchiveFormConfig archiveFormConfig;

        select firstonly RecId from archiveFormConfig
            where archiveFormConfig.ServerId == AVADAIParameters::find().ServerId
				&& archiveFormConfig.Form == _form;

        return archiveFormConfig.RecId != 0;
    }

/// <summary>
/// retrieve modified field.
/// </summary>
/// <param name = "FieldName">field name</param>
/// <param name = "Interger">integer.</param>
public void modifiedFieldValue(FieldName _fieldName, int _arrayIndex = 1)
{
    super(_fieldName, _arrayIndex);

    switch (_fieldName)
    {
        case fieldStr(AVADAIArchiveFormConfig, InsertCompany):
            if (this.InsertCompany == NoYes::No)
            {
                this.EscapeStrCompany = '';
            }
            break;
    }
}

/// <summary>
/// Validate write
/// </summary>
public boolean validateWrite()
{
    boolean ret = super();
    if (!this.url)
    {
        ret = checkFailed(strFmt("@SYS50104", fieldPName(AVADAIArchiveFormConfig, URL)));
    }

    if (!this.EscapeStr)
    {
        ret = checkFailed(strFmt("@SYS50104", fieldPName(AVADAIArchiveFormConfig, EscapeStr)));
    }

    if (this.InsertCompany == NoYes::Yes && !this.EscapeStrCompany)
    {
        ret = checkFailed(strFmt("@SYS50104", fieldPName(AVADAIArchiveFormConfig, EscapeStrCompany)));
    }

    return ret;
}

/// <summary>
/// insert
/// </summary>
public void insert()
{
    if (this.InsertCompany == NoYes::No)
    {
        this.EscapeStrCompany = '';
    }

    super();
}

/// <summary>
/// update
/// </summary>
public void update()
{

    if (this.InsertCompany == NoYes::No)
    {
        this.EscapeStrCompany = '';
    }

    super();
}
